INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103135,0,0,'Hey mon, you not be comin\' ta Zen\'tabra for some fish. What ya be wantin\'?',12,0,100.0,0,0,0,105677,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103136,0,0,'So, time to see if we can really be makin\' this happen. This gonna\' be needin\' everything we have ta give and more.',12,0,100.0,1,0,0,105873,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103136,3,0,'De spirits, they be silent ta\' me on dis. That mean dey not opposed ta it either. Very well, I\'ll meet ye at da ritual.',12,0,100.0,1,0,0,105881,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103489,3,0,'I will remove these nightmarish vines from our path, but the source of fel that gave birth to them is somewhere else. $n, find this source and destroy it!',12,0,100.0,0,0,0,0,0,'LegionCore');
