INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104385,0,0,'The first trial will test your might against the strongest of my followers. Show me that you possess the strength of the bear!',12,0,100.0,0,0,0,107141,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104385,1,0,'Before you awaits your next trial. Defeat the spirits and prove you possess the courage of the bear!',12,0,100.0,0,0,0,107154,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104385,2,0,'Magnificent! Your courage is undeniable! A final trial awaits you.',12,0,100.0,0,0,0,107155,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104385,3,0,'The final trial will not be easy, druid. Speak with me when you are ready.',12,0,100.0,0,0,0,107508,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104385,4,0,'Very good, $n! The spirit of the bear truly dwells within you!',12,0,100.0,0,0,0,107516,0,'LegionCore');
