INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104535,0,0,'Good to see you made it, $n. We need only a few more things before we can begin.',12,0,100.0,0,0,0,106956,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104535,1,0,'Great Ursol, wise bear of the woods, this daughter of the wilds calls to you! Please accept these humble offerings and grant us an audience!',12,0,100.0,0,0,0,107322,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104535,2,0,'Now that we have Ursol\'s blessing, we can travel into the Emerald Dream and retrieve the claws! Come, $n, let\'s not waste a single minute!',12,0,100.0,0,0,0,107662,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104535,3,0,'Calm your mind, let go and your spirit will enter into the Dream. I\'ll join you soon.',12,0,100.0,0,0,0,106957,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104535,4,0,'There is a noise from behind you!',41,0,100.0,1,0,0,107346,0,'LegionCore');
