INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104577,0,0,'May the ancients bless us all.',12,0,100.0,0,0,0,107061,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104577,1,0,'For centuries I have watched over G\'Hanir. Today it nearly fell to the corruption I swore to fight. It is time for another to take my place.',12,0,100.0,0,0,0,107326,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104577,2,0,'Therefore, I hereby pass along my station to $p. A true protector of life... a true guardian of the Dream!',12,0,100.0,0,0,0,107327,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104714,0,0,'That creature unworthy of great Ursol! I crush it!',12,0,100.0,0,0,0,107149,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104714,1,0,'Too... strong! Stop! No more fight!',14,0,100.0,0,0,0,107150,0,'LegionCore');
